def word_counts(text):
    counts = {}
    for raw in text.split():
        word = raw.strip(".,!?;:\"'").lower()
        if word:
            counts[word] = counts.get(word, 0) + 1
    return counts


def top_words(counts, n):
    ranked = []
    for word, count in counts.items():
        ranked.append((-count, word))
    ranked.sort()
    result = []
    for negative, word in ranked[:n]:
        result.append((word, -negative))
    return result


def shared_letters(a, b):
    letters_a = set()
    for c in a.lower():
        if c.isalpha():
            letters_a.add(c)
    letters_b = set()
    for c in b.lower():
        if c.isalpha():
            letters_b.add(c)
    return sorted(letters_a & letters_b)

unitTests:
TEXT = 'The cat and the hat. "The end!" said the cat.'

@test("counting")
def _():
    counts = word_counts(TEXT)
    check_eq(counts["the"], 4)
    check_eq(counts["cat"], 2)
    check_eq(counts["end"], 1)
    check("" not in counts, "empty words must not be counted")
    check_eq(word_counts("... !!!"), {})

@test("top words")
def _():
    counts = word_counts(TEXT)
    check_eq(top_words(counts, 3), [("the", 4), ("cat", 2), ("and", 1)])
    check_eq(top_words({"b": 1, "a": 1}, 5), [("a", 1), ("b", 1)])
    check_eq(top_words({}, 2), [])

@test("shared letters")
def _():
    check_eq(shared_letters("Python", "typo"), ["o", "p", "t", "y"])
    check_eq(shared_letters("abc", "xyz"), [])

